-- Closing-cost (fee) templates. Staff pick one to fill in a comparison's closing costs; staff can edit and save them.
create table if not exists public.fee_templates (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  state text,
  items jsonb not null default '[]'::jsonb,   -- [{name, amt, pct, by: B|S|L, apr, prepaid}]
  updated_by uuid default auth.uid() references auth.users(id) on delete set null,
  updated_at timestamptz not null default now()
);
alter table public.fee_templates enable row level security;
drop policy if exists "staff manage fee templates" on public.fee_templates;
create policy "staff manage fee templates" on public.fee_templates
  for all to authenticated using (public.is_staff()) with check (public.is_staff());
revoke all on public.fee_templates from anon;
grant select, insert, update, delete on public.fee_templates to authenticated;
drop trigger if exists fee_templates_touch on public.fee_templates;
create trigger fee_templates_touch before update on public.fee_templates
  for each row execute function public.touch_updated_at();

